import { HttpClient, HttpParams } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { environment } from "../../environments/environment";

@Injectable({
    providedIn: 'root'
})
export class SplitPaymentService {

    private baseUrlSplitPayment = environment.splitPaymentAPI;

    input: any = null;
    output: any = null;
    header: any = null;
    
    constructor(private http: HttpClient) { }
    
    calcularTributosSplitPayment(body: any): Observable<any> {
        return this.http.post<any>(`${this.baseUrlSplitPayment}/split-payment`, body, { observe: 'response' });
    }

    consultarCnpjCpf(data: Date): Observable<any> {
        let params: HttpParams = new HttpParams();
        params = params.append('dataOperacao', this.formatarDataApi(data));
        return this.http.get<any>(`${this.baseUrlSplitPayment}/split-payment/cnpj-cpf`, {params: params});
    }

    // para transformar a data no formato YYYY-MM-DD
    
    formatarDataApi(date: Date | string): string {
        const d = new Date(date);
        if (isNaN(d.getTime())) {
            throw new Error('Erro na formatação de data.');
        }
        return d.toISOString().slice(0, 10);
    }

}
