import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DatePickerComponent, DefaultsService, GovBrDatePickerModule, GovBrDirectivesModule, GovBrInputModule, GovBrSelectModule } from '@serpro/ngx-dsgovbr';
import { CalcularService } from '../../services/calcular.service';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { SimuladorSimplificadoResultadoComponent } from './simulador-simplificado-resultado/simulador-simplificado-resultado.component';
import { BarraBotoesComponent } from '../diversos/barra-botoes/barra-botoes.component';
import { MensagemService } from '../../services/mensagem.service';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { DadosCalculadoraService } from '../../services/dados-calculadora.service';
import { SplitPaymentService } from '../../services/split-payment.service';
import { CpfCnpjPipe } from '../../services/pipes/cpf-cnpj.pipe';

@Component({
  selector: 'simulador-split-payment-simplificado',
  templateUrl: './simulador-split-payment-simplificado.component.html',
  styleUrl: './simulador-split-payment-simplificado.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    TooltipModule,
    GovBrDatePickerModule,
    GovBrSelectModule,
    GovBrInputModule,
    MyTitleComponent,
    SimuladorSimplificadoResultadoComponent,
    BarraBotoesComponent,
    GovBrDirectivesModule
  ]
})

export class SimuladorSplitPaymentSimplificadoComponent implements OnInit, OnDestroy {

  @ViewChild('datePicker') datePicker: DatePickerComponent | undefined;

  private readonly subscriptions: Subscription = new Subscription();

  botaoCalcularDisabled: boolean = false;
  cadastro: string = '';
  cpfCnpj: string = '';
  minDate: Date;

  cnpjCpf: any[] = [];

  private readonly cpfCnpjPipe = new CpfCnpjPipe();

  constructor(
    private readonly calcularService: CalcularService,
    private readonly formBuilder: FormBuilder,
    private mensagemService: MensagemService,
    private splitPaymentService: SplitPaymentService
  ) {
    this.minDate = new Date('2027-01-01 00:00:00');
  }

  calculadoraOutput: any;
  form!: FormGroup;

  ngOnInit(): void {

    this.form = this.formBuilder.group({
      cadastroControl: [{ value: null, disabled: false }, [Validators.required]],
      baseCalculoControl: [{ value: 200.00, disabled: false }, [Validators.required]],
      dataControl: [{ value: new Date('2027/01/01'), disabled: false }, [Validators.required]],
    });

    this.consultarCnpjCpf();
    this.formControlSubscription();

  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  consultarCnpjCpf() {
    this.splitPaymentService.consultarCnpjCpf(this.form.get('dataControl')?.value).subscribe({
      next: (data) => {
        this.cnpjCpf = [];

        for (let x of data) {
          this.cnpjCpf = [...this.cnpjCpf, {
            label: this.cpfCnpjPipe.transform(x),
            valor: x
          }]
        }
      }
    })
  }

  calcular() {

    this.calculadoraOutput = null;

    if (this.form.valid) {

      let body: any = {
        fatoGerador: this.calcularService.formatarDataParaBackend(this.form.get('dataControl')?.value),
        baseCalculo: this.form.get('baseCalculoControl')?.value,
        cpfCnpj: this.form.get('cadastroControl')?.value?.valor
      }

      this.splitPaymentService.calcularTributosSplitPayment(body).subscribe({
        next: (data) => {

          this.splitPaymentService.header = data.headers.get('x-warning-dados-simulados') || null;
          this.splitPaymentService.input = body;
          this.splitPaymentService.output = data.body;
          this.calculadoraOutput = data.body;

          if (!this.splitPaymentService.header) {
            this.mensagemService.mostrar('Sucesso', 'Sucesso', 'Cálculo realizado com sucesso.');
          }
          if (this.splitPaymentService.header) {
            this.mensagemService.mostrar('Aviso', 'Aviso', this.obterAviso(this.splitPaymentService.header));
          }
          
        },
        error: (error) => {
          console.error('Erro no processamento:', error);
          this.mensagemService.mostrar('Erro', 'Erro', 'Ocorreu um erro ao processar a solicitação.');
        }
      })
    } else {
      this.mensagemService.mostrar('Erro', 'Erro', 'Formulário inválido.');
    }
  }

  formControlSubscription() {
    this.subscriptions.add(
      this.form.get('dataControl')?.valueChanges.subscribe(value => {
        this.dataControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('cadastroControl')?.valueChanges.subscribe(value => {
        this.cadastroControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('baseCalculoControl')?.valueChanges.subscribe(value => {
        this.baseCalculoControlChange(value);
      })
    );
  }

  baseCalculoControlChange(event: any) {
    this.calculadoraOutput = null;
  }

  cadastroControlChange(event: string) {
    this.calculadoraOutput = null;
  }

  dataControlChange(event: any) {
    this.calculadoraOutput = null;
    this.form.patchValue({ cadastroControl: null });
    this.consultarCnpjCpf();
  }

  dataControlInput(event: any) {
    this.calculadoraOutput = null;
    if (event.srcElement.value.length >= 10) {
      this.datePicker?.selectionInlineDone(new Date(event.srcElement.value));
    }
  }

  resetarValores() {
    this.calculadoraOutput = null;
  }

  limpar = () => {
    this.form.reset();
    this.resetarValores();
  }

  AVISOS: { [key: string]: string } = {
    '0': '',
    '1': 'A data do Fato Gerador não está dentro do período esperado. Para fins de simulação, utilize datas a partir de 01/01/2027.',
    '2': '',
    '3': '',
    '4': '',
    '5': 'O Split Payment Simplificado ainda não possui alíquotas definidas em lei. Para fins de simulação foram apresentados CNPJ\'s e alíquotas fictícias.',
  };

  obterAviso(header: any): string {

    if (!header) {
      return '';
    }
    const headerKey = String(header);
    return this.AVISOS[headerKey] || '';
  }

}
